using IndieRun;
using System.IO;
using System.Reflection;
using System.Security.AccessControl;
using System.Security.Principal;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Threading;
using System.Xml.Linq;

static class Program
{
    static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
    static object? Call(object o,string method,params object?[] args)=>o.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.DeclaredOnly)!.Invoke(o,args);
    static T Get<T>(object o,string field)=>(T)o.GetType().GetField(field,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public)!.GetValue(o)!;
    static void Set(object o,string field,object value)=>o.GetType().GetField(field,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public)!.SetValue(o,value);
    static void Wait(Task task){var frame=new DispatcherFrame();task.ContinueWith(_=>Application.Current.Dispatcher.BeginInvoke(new Action(()=>frame.Continue=false)));Dispatcher.PushFrame(frame);task.GetAwaiter().GetResult();}
    static void Refuse(Action action){try{action();}catch(Exception ex)when(ex is IOException or UnauthorizedAccessException or ArgumentException or JsonException){return;}throw new Exception("Expected refusal");}
    [STAThread] static int Main(string[] args)
    {
        var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var styles=XDocument.Load(Path.Combine(AppContext.BaseDirectory,"styles-source.xaml")).Root!.Elements().Single().Elements().Single();app.Resources=(ResourceDictionary)XamlReader.Parse(styles.ToString(),new ParserContext{BaseUri=new Uri(AppContext.BaseDirectory)});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(app.Dispatcher));
        var root=Path.Combine(Path.GetFullPath(args[0]),"run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var results=new List<object>();int failed=0;
        void Test(string name,Action<string> action){var folder=Path.Combine(root,name);Directory.CreateDirectory(folder);try{action(folder);results.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;results.Add(new{name,status="FAIL",error=ex.ToString()});Console.WriteLine("FAIL "+name+": "+ex.Message);}}
        Package Game(string root,string relative="input/Game")
        {var path=Path.GetFullPath(Path.Combine(root,relative));Directory.CreateDirectory(path);File.WriteAllText(Path.Combine(path,"Game.exe"),"indierun test fixture; not executable");return new(){Registered=false,IsReal=true,Id=Guid.NewGuid().ToString("N"),Source=path,SearchRoot=Path.Combine(root,"input"),DetectedRoot=path,Folder=Path.GetFileName(path),Name=Path.GetFileName(path)};}
        MainWindow Window(string folder,List<Package> games)
        {
            var w=new MainWindow();var scan=GameScanner.Scan(Path.Combine(folder,"input"));Set(w,"packages",games);Set(w,"selected",games[0]);Set(w,"snapshot",scan);Set(w,"source",Path.Combine(folder,"input"));Set(w,"searchLocations",new List<SearchLocation>{new(){Path=Path.Combine(folder,"input")}});Set(w,"destination",Path.Combine(folder,"library"));Set(w,"playerRoot",Path.Combine(folder,"library"));Set(w,"checkpoints",games.Select(p=>WorkspaceReconciler.Capture(p,scan)).ToList());return w;
        }
        void Close(MainWindow w){Set(w,"closingWithoutSave",true);w.Close();}
        void EnableSave(MainWindow w){var store=Get<WorkspaceStore>(w,"workspaceStore");Set(w,"workspaceLock",store.AcquireLock());Set(w,"sessionReady",true);Set(w,"identityNoticeAccepted",true);}
        Test("discovery-does-not-register-or-write-marker",folder=>{var p=Game(folder);var scan=GameScanner.Scan(p.SearchRoot);var found=WorkspaceReconciler.Discover(scan,[]).Single();Check(!GameRegistration.IsAdded(found)&&!File.Exists(Path.Combine(p.Source,LibraryStore.MarkerName)),"Discovery added game");});
        Test("legacy-workspace-remains-visible-with-settings",folder=>{var p=Game(folder);p.Registered=null;p.Alias="내 별칭";var w=Window(folder,[p]);try{Call(w,"ApplyWorkspace",new WorkspaceDocument{SearchRoot=p.SearchRoot,Destination=Path.Combine(folder,"library"),Packages=[p]});Check(p.Registered==true&&p.Alias=="내 별칭","Legacy disappeared");}finally{Close(w);}});
        Test("unadded-candidates-stay-out-of-player",folder=>{var a=Game(folder);var b=Game(folder,"input/Saved");b.Registered=true;var w=Window(folder,[a,b]);try{var visible=((IEnumerable<Package>)Call(w,"VisibleGames")!).ToList();Check(visible.Count==1&&visible[0].Id==b.Id,"Candidate leaked into player");}finally{Close(w);}});
        Test("move-estimate-uses-current-scan-when-saved-size-is-zero",folder=>{var p=Game(folder);p.Gb=0;var w=Window(folder,[p]);try{Check((long)Call(w,"PackageBytes",p)! ==new FileInfo(Path.Combine(p.Source,"Game.exe")).Length,"Move estimate ignored scan bytes");}finally{Close(w);}});
        Test("normal-registration-preserves-files-and-folder-name",folder=>{var p=Game(folder);p.Alias="내 게임";p.Genres=["퍼즐"];var before=File.ReadAllBytes(Path.Combine(p.Source,"Game.exe"));var result=GameRegistration.Add(p,[],GameScanner.Scan(p.SearchRoot),Path.Combine(folder,"library"));Check(!result.LocalOnly&&result.Id==p.Id&&result.Library!.Document.Games.Single().LastKnownPath==p.Source,"Not registered at original path");Check(File.ReadAllBytes(Path.Combine(p.Source,"Game.exe")).SequenceEqual(before)&&Directory.Exists(p.Source),"Moved or modified executable");});
        Test("duplicate-id-is-refused-without-changing-identity",folder=>{var p=Game(folder);LibraryStore.EnsureIdentity(p.Source,p.Id);var other=Game(folder,"input/Copy");File.Copy(Path.Combine(p.Source,LibraryStore.MarkerName),Path.Combine(other.Source,LibraryStore.MarkerName));var scan=GameScanner.Scan(p.SearchRoot);Refuse(()=>GameRegistration.Add(p,[],scan,Path.Combine(folder,"library")));Check(LibraryStore.ReadIdentity(other.Source)!.GameId==p.Id&&!File.Exists(Path.Combine(folder,"library",LibraryStore.JsonName)),"Duplicate changed data");});
        Test("corrupt-identity-is-not-bypassed-as-local-registration",folder=>{var p=Game(folder);File.WriteAllText(Path.Combine(p.Source,LibraryStore.MarkerName),"bad marker");Refuse(()=>GameRegistration.Add(p,[],GameScanner.Scan(p.SearchRoot),Path.Combine(folder,"library")));});
        Test("missing-identity-repair-is-explicit-and-keeps-original-id",folder=>{var p=Game(folder);p.ReviewState="identity";var scan=GameScanner.Scan(p.SearchRoot);Refuse(()=>GameRegistration.Add(p,[],scan,Path.Combine(folder,"library")));var result=GameRegistration.Add(p,[],scan,Path.Combine(folder,"library"),false,true);Check(!result.LocalOnly&&result.Id==p.Id&&LibraryStore.ReadIdentity(p.Source)!.GameId==p.Id,"Identity repair changed ID");});
        Test("read-only-folder-allows-local-registration-but-not-move-registration",folder=>{var p=Game(folder);var scan=GameScanner.Scan(p.SearchRoot);var dir=new DirectoryInfo(p.Source);var old=FileSystemAclExtensions.GetAccessControl(dir);var restricted=FileSystemAclExtensions.GetAccessControl(dir);restricted.AddAccessRule(new FileSystemAccessRule(WindowsIdentity.GetCurrent().User!,FileSystemRights.CreateFiles,AccessControlType.Deny));try{FileSystemAclExtensions.SetAccessControl(dir,restricted);var r=GameRegistration.Add(p,[],scan,Path.Combine(folder,"library"));Check(r.LocalOnly&&r.Id==p.Id&&r.Library==null&&!File.Exists(Path.Combine(p.Source,LibraryStore.MarkerName)),"No local fallback");Refuse(()=>GameRegistration.Add(p,[],scan,Path.Combine(folder,"library"),false));}finally{FileSystemAclExtensions.SetAccessControl(dir,old);}});
        Test("nested-scope-previous-preserves-alias-tags-and-other-selection",folder=>{var p=Game(folder,"input/Product/Bundle/Game");var other=Game(folder,"input/Other");File.WriteAllText(Path.Combine(folder,"input/Product/Bundle/guide.txt"),"guide");p.Alias="별칭";p.Genres=["퍼즐"];var w=Window(folder,[p,other]);try{Get<HashSet<string>>(w,"organizeSelection").Add(other.Id);Call(w,"SetScope",Path.Combine(folder,"input/Product/Bundle"),true);Call(w,"SetScope",Path.Combine(folder,"input/Product"),true);Call(w,"ResetScope_Click",w,new RoutedEventArgs());Check(p.Source.EndsWith("Bundle")&&p.ScopeHistory.Count==1,"Did not restore previous level");Call(w,"ResetScope_Click",w,new RoutedEventArgs());Check(p.Source==p.DetectedRoot&&p.Alias=="별칭"&&p.Genres.Single()=="퍼즐"&&Get<HashSet<string>>(w,"organizeSelection").Contains(other.Id),"Unrelated edits lost");}finally{Close(w);}});
        Test("overlapping-scope-remains-unchanged",folder=>{var a=Game(folder,"input/Pack/One");var b=Game(folder,"input/Pack/Two");b.Registered=true;LibraryStore.EnsureIdentity(b.Source,b.Id);var w=Window(folder,[a,b]);try{new System.Windows.Interop.WindowInteropHelper(w).EnsureHandle();var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(30)};timer.Tick+=(_,_)=>{foreach(var dialog in app.Windows.OfType<AppDialog>().ToList())dialog.Close();};timer.Start();try{Call(w,"SetScope",Path.Combine(folder,"input/Pack"),true);}finally{timer.Stop();}Check(a.Source==a.DetectedRoot&&a.ScopeHistory.Count==0&&Get<Border>(w,"OrganizeWarning").Visibility==Visibility.Visible,"Overlap accepted");}finally{Close(w);}});
        Test("partial-add-continues-and-only-failed-item-stays-selected",folder=>{var a=Game(folder);var b=Game(folder,"input/Missing");var w=Window(folder,[a,b]);try{EnableSave(w);var picked=Get<HashSet<string>>(w,"organizeSelection");picked.Add(a.Id);picked.Add(b.Id);Directory.Move(b.Source,b.Source+"-moved");Wait((Task)Call(w,"AddPickedGamesAsync",false)!);Check(a.Registered==true&&b.Registered==false&&picked.SetEquals([b.Id]),"Batch stopped or lost failed selection: "+JsonSerializer.Serialize(new{a=a.Registered,b=b.Registered,picked=picked.ToList(),errors=Get<Dictionary<string,string>>(w,"registrationErrors"),notice=Get<TextBlock>(w,"Notice").Text}));var doc=new WorkspaceStore(Get<WorkspaceStore>(w,"workspaceStore").FilePath).Load().Document!;Check(doc.Packages.Single(p=>p.Id==a.Id).Registered==true,"Registration not durable");}finally{Close(w);}});
        Test("add-keeps-default-executable-unset-and-play-settings",folder=>{var a=Game(folder);var w=Window(folder,[a]);try{EnableSave(w);Set(w,"playerDocument",new PlayerDocument{Games=[new(){Id=a.Id,Favorite=true,Arguments="--keep"}]});Get<HashSet<string>>(w,"organizeSelection").Add(a.Id);Wait((Task)Call(w,"AddPickedGamesAsync",false)!);var play=Get<PlayerDocument>(w,"playerDocument").Games.Single();Check(play.Executable==""&&play.Favorite&&play.Arguments=="--keep","Settings lost or executable inferred");Check(a.ScopeHistory.Count==0&&Directory.Exists(a.Source),"Wrong range or moved");}finally{Close(w);}});
        Test("registration-mode-and-scope-history-survive-workspace-save",folder=>{var p=Game(folder,"input/Product/Game");p.Registered=true;p.LocalRegistration=true;var doc=new WorkspaceDocument{SearchRoot=p.SearchRoot,Destination=Path.Combine(folder,"library"),Packages=[p],IdentityNoticeAccepted=true};var store=new WorkspaceStore(Path.Combine(folder,"state.json"));store.Save(doc);var reload=store.Load().Document!;Check(reload.Packages[0].Registered==true&&reload.Packages[0].LocalRegistration&&reload.IdentityNoticeAccepted,"Registration mode lost");});
        Test("main-backup-move-and-undo-use-selected-target-without-changing-settings-root",folder=>
        {
            var p=Game(folder);p.Registered=true;var original=p.Source;var w=Window(folder,[p]);try
            {
                EnableSave(w);var metadataRoot=Get<string>(w,"destination");Set(w,"backupStorageRoot",Path.Combine(folder,"backups"));var player=new PlayerDocument{Games=[new(){Id=p.Id,Favorite=true,Arguments="--keep"}]};Set(w,"playerDocument",player);new PlayerStore(metadataRoot).Save(player);
                var target=Path.Combine(folder,"chosen-target");Wait((Task)Call(w,"StartMoveBatchAsync",new List<Package>{p},target)!);
                var service=new BackupEngine(Path.Combine(folder,"backups"));var move=service.ListMoves().Single();Check(move.Status=="Completed"&&Directory.Exists(Path.Combine(target,p.Name))&&!Directory.Exists(original),"UI move flow did not finish");Check(Get<string>(w,"destination")==metadataRoot&&new PlayerStore(metadataRoot).Load().Games.Single().Favorite,"Moving changed execution settings root");Check(service.ListJobs().Single().Status=="Completed","Backup not retained");
                Wait((Task)Call(w,"RunMoveJob",move,true)!);Check(Directory.Exists(original)&&service.ListMoves().Single().Status=="RolledBack","UI undo failed");Check(LibraryStore.ReadIdentity(original)!.GameId==p.Id,"Identity lost on restore");
            }finally{Close(w);}
        });
        foreach(var size in new[]{(1090d,720d),(1350d,870d)})foreach(var scale in new[]{1d,1.5d})Test($"layout-and-selection-stability-{size.Item1}-{scale}",folder=>
        {var p=Game(folder,"input/Product/Game");var b=Game(folder,"input/Other");var w=Window(folder,[p,b]);try{w.FontSize=13*scale;Call(w,"Render");var root=(Grid)w.Content;void Layout(){root.Measure(new Size(size.Item1,size.Item2));root.Arrange(new Rect(0,0,size.Item1,size.Item2));root.UpdateLayout();}Layout();var list=Get<StackPanel>(w,"CandidateList");var before=((Grid)list.Children[1]).TranslatePoint(new Point(),list).Y;Get<HashSet<string>>(w,"organizeSelection").Add(p.Id);Call(w,"Render");Layout();var after=((Grid)list.Children[1]).TranslatePoint(new Point(),list).Y;Check(Math.Abs(before-after)<.5,"Selection shifted cards");Call(w,"SetScope",Path.Combine(folder,"input/Product"),true);Layout();foreach(var name in new[]{"AddGamesButton","ResetScopeButton"}){var button=Get<Button>(w,name);var pos=button.TranslatePoint(new Point(),root);Check(button.Visibility==Visibility.Visible&&pos.X>=0&&pos.X+button.ActualWidth<=size.Item1+.5&&pos.Y+button.ActualHeight<=size.Item2+.5,"Action clipped: "+name);}}finally{Close(w);}});
        File.WriteAllText(args[1],JsonSerializer.Serialize(new{root,total=results.Count,passed=results.Count-failed,failed,results},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"RESULT {results.Count-failed}/{results.Count}");return failed==0?0:1;
    }
}
